[WRITE] Update the menu in index.html. Add a data-type to each item:
      <li data-type='drink'>Espresso — $3</li>
      <li data-type='drink'>Cortado — $4</li>
      <li data-type='drink'>Pour Over — $5</li>
      <li data-type='drink'>Cold Brew — $5</li>
      <li data-type='food'>Croissant — $4</li>

Above the menu add filter buttons:
      <div class='filters'>
        <button data-filter='all'>All</button>
        <button data-filter='drink'>Drinks</button>
        <button data-filter='food'>Food</button>
      </div>

In script.js:
      document.querySelectorAll('.filters button').forEach(btn => {
          btn.addEventListener('click', () => {
              const f = btn.dataset.filter;
              document.querySelectorAll('#menu li').forEach(li => {
                  li.style.display = (f === 'all' || li.dataset.type === f) ? 'block' : 'none';
              });
          });
      });

